//! Schema for the adapted, stored game-data catalog.
//!
//! This is PoBR's **own minimal JSON schema**, generated by
//! `pobr-data-adapter` from GGG's raw `.dat` export (pathofexile-dat
//! output) by resolving foreign keys and denormalizing, landing in the
//! repo under `data/<poe_version>/` (a three-layer layout: `base/` fully
//! auto-regenerated, `overlay/` vendor-extracted, `generated/`
//! deterministic cache — see P1). Loaded at runtime via serde by the
//! loader (`pobr-gamedata`).
//!
//! Design goals: decoupled from GGG's raw column names / PoB's generated
//! Lua; keeps only the fields calc/display need; stable string IDs;
//! pin-able versions, diff-friendly (arrays sorted by id).
//!
//! Modules are split by data-domain cohesion; every type is fully
//! re-exported via `pub use` here, so external code always references them
//! as `pobr_data::catalog::X` (the split doesn't break existing paths).

pub mod items;
pub mod manifest;
pub mod mods;
pub mod skills;
pub mod tree;

// Empty shells for the nine-table schema (pre-created to avoid parallel-work conflicts; W2 fills in the types)
