pub mod high_precision_mods;
pub mod local_mods;

// Per-skill override-value overlay schema (vendor Lua extraction)
pub mod skill_overrides;

// SkillStatMap overlay schema (vendor Lua extraction, skill_stat_map/v1)
pub mod stat_map;

//  StatDescriptions overlay schema (the second stat_id → canonical-text channel)
pub mod stat_descriptions;
// Phase 7.1: mod-line input translation templates (i18n/<lang>/stat_lines.json)
pub mod i18n_stat_lines;
pub use i18n_stat_lines::StatLineTemplate;
//  StatId→Modifier mapping table (stat_descriptions baked by the engine's parser)
